// Embeds assets/og-room.jpg into src/http/og-image.ts so the Worker can serve it.
// Run after replacing the image: node scripts/embed-og.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../", import.meta.url);
const jpg = readFileSync(fileURLToPath(new URL("assets/og-room.jpg", root)));
const source =
  "/** Generated by scripts/embed-og.mjs from assets/og-room.jpg. Do not edit. */\n" +
  `export const OG_IMAGE_BASE64 = "${jpg.toString("base64")}";\n`;
writeFileSync(fileURLToPath(new URL("src/http/og-image.ts", root)), source);
console.log(`Wrote src/http/og-image.ts (${jpg.length} bytes of JPEG)`);
